// Regenerate Settings defaults from the two shipped keymaps.
// Runs of bindings both keymaps share are emitted once, so the generated file itself
// keeps the no-repeated-code rule the CI check holds every source file to.
import { readFile, writeFile } from "node:fs/promises";
import { shippedKeymap } from "../kanso/mods/kanso-panel/platform-keymap.js";

const root = new URL("../", import.meta.url);
const files = [...new Set(["macos", "windows"].map(shippedKeymap))];
const maps = Object.fromEntries(await Promise.all(files.map(async (file) => [file, JSON.parse(await readFile(new URL(file, root), "utf8"))])));

const q = (text) => JSON.stringify(text);
const indent = (n) => " ".repeat(n);

// Maximal runs (two or more) of consecutive entries the other section shares, key and action alike,
// and holds in the same order, so one const can stand in for both.
function sharedRuns(entries, otherEntries) {
  const at = new Map(otherEntries.map(([key, value], index) => [key, { value, index }]));
  const marks = entries.map(([key, value], index) => {
    const found = at.get(key);
    return found && found.value === value ? { index, at: found.index } : null;
  });
  const runs = [];
  marks.forEach((mark, i) => {
    if (!mark) return;
    const prev = runs.at(-1);
    if (prev && prev.end === i && prev.atEnd + 1 === mark.at) { prev.end = i + 1; prev.atEnd = mark.at; }
    else runs.push({ start: i, end: i + 1, atStart: mark.at, atEnd: mark.at });
  });
  return runs.filter((run) => run.end - run.start >= 2);
}

const sharedNames = new Map(); // entries json -> const name
const plans = files.map((file, f) => {
  const other = maps[files[1 - f]];
  return Object.entries(maps[file]).map(([section, obj]) => {
    const entries = Object.entries(obj);
    const otherSection = other?.[section];
    const runs = otherSection ? sharedRuns(entries, Object.entries(otherSection)) : [];
    const pieces = [];
    let at = 0;
    for (const run of runs) {
      const slice = entries.slice(run.start, run.end);
      const id = q(slice);
      if (!sharedNames.has(id)) sharedNames.set(id, `onBoth${sharedNames.size + 1}`);
      pieces.push({ kind: "literal", entries: entries.slice(at, run.start) });
      pieces.push({ kind: "shared", name: sharedNames.get(id) });
      at = run.end;
    }
    pieces.push({ kind: "literal", entries: entries.slice(at) });
    return [section, pieces.filter((piece) => piece.kind === "shared" || piece.entries.length)];
  });
});

const lines = ["// Generated by scripts/sync-keys.mjs."];
for (const [id, name] of sharedNames) {
  lines.push(`const ${name} = {`, ...JSON.parse(id).map(([key, value]) => `${indent(2)}${q(key)}: ${q(value)},`), "};");
}
lines.push("");
lines.push("export const DEFAULT_KEYS = {");
files.forEach((file, f) => {
  lines.push(`${indent(2)}${q(file)}: {`);
  plans[f].forEach(([section, pieces]) => {
    lines.push(`${indent(4)}${q(section)}: {`);
    for (const piece of pieces) {
      if (piece.kind === "shared") lines.push(`${indent(6)}...${piece.name},`);
      else for (const [key, value] of piece.entries) lines.push(`${indent(6)}${q(key)}: ${q(value)},`);
    }
    lines.push(`${indent(4)}},`);
  });
  lines.push(`${indent(2)}},`);
});
lines.push("};");
await writeFile(new URL("kanso/mods/kanso-settings/defaults.js", root), `${lines.join("\n")}\n`);
